(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.3)*16 + Math.sin(x*0.02+t*0.32)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.17)*9 + Math.sin((x+y)*0.009-t*0.14)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*45, 0.065, 2.4, 1.15],
    [200+Math.sin(t*0.38+6)*110, 150+Math.cos(t*0.48+3)*75, 0.085, 1.8, 1.0]
  ];
  let aS=0, iS=0, aH=0, iH=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), b=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const ah=Math.sin(d*f*1.618-t*sp*0.78)*0.5, bh=Math.sin(d*f*0.434+t*sp*1.23+0.7)*0.4;
    aS+=a*w; iS+=b*w; aH+=ah*w; iH+=bh*w;
  }
  const tw=9;
  const act=(aS+aH)/tw, inh=(iS+iH)/tw;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07+t*1.7)*Math.cos(sy*0.06-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*6+t*0.8)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi=()=>{
    let md=999,mi=0;
    for(let i=0;i<7;i++){
      const vx=120+i*55+Math.sin(t*0.4+i*1.1)*30;
      const vy=60+Math.cos(t*0.35+i*0.9)*40+((i*37)%80);
      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){md=d;mi=i;}
    }
    return Math.sin(md*0.15-t*0.8+mi)*0.2;
  };
  const vo=voronoi();
  const blend=reaction*0.6+cell*0.2+vo*0.2;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,85],[18,95,115],[25,150,130],[160,175,70],
    [210,155,65],[195,90,60],[155,45,55],[90,18,45],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const smoothF=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,1-dist/280)*0.15*Math.sin(t*0.6)*0.5+1;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*smoothF)*lum*edge*glow)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*smoothF)*lum*edge*glow)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*smoothF)*lum*edge*glow)|0)
  ];
}
